// Classify every SO line against the stored SO. The child-table row `id` is the only
// stable handle -- line_index is positional and table_so has no fm_key.
const mode = {{workflowparams:mode}};
const prevRaw = {{workflowparams:prev_table_so}};
const nextRaw = {{workflowparams:next_table_so}};

const flat = (rows) =>
  (Array.isArray(rows) ? rows : []).flatMap((r) =>
    [r].concat(Array.isArray(r && r.children) ? r.children : [])
  );
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const sid = (v) => String(v === null || v === undefined ? "" : v);
const round3 = (v) => Math.round(num(v) * 1000) / 1000;

const prevLines = flat(prevRaw).filter((r) => r);
const nextLines = flat(nextRaw).filter((r) => r);

const prevById = {};
prevLines.forEach((r) => { if (r.id) prevById[sid(r.id)] = r; });
const nextById = {};
nextLines.forEach((r) => { if (r.id) nextById[sid(r.id)] = r; });

const changes = [];
const materialIds = [];
const pushMat = (m) => {
  const s = sid(m);
  if (s && materialIds.indexOf(s) < 0) materialIds.push(s);
};
const entry = (row, kind, prevQty, nextQty, prevItem, nextItem, base) => ({
  soLineId: sid(row.id),
  kind: kind,
  prevQty: prevQty,
  nextQty: nextQty,
  prevItem: prevItem,
  nextItem: nextItem,
  uomId: sid(row.so_item_uom),
  desc: sid(row.so_desc),
  itemCode: sid(row.item_id),
  lineIndex: sid(row.line_index),
  deliveredQty: round3(base.delivered_qty),
  plannedQty: round3(base.planned_qty)
});

if (mode === "append") {
  // Pass B. next_table_so is the PERSISTED table, so an added row already carries the
  // platform-assigned id it did not have when pass A ran.
  nextLines.forEach((r) => {
    if (!r.id || prevById[sid(r.id)] || !r.item_name) return;
    changes.push(entry(r, "added", 0, round3(r.so_quantity), "", sid(r.item_name), r));
    pushMat(r.item_name);
  });
} else {
  nextLines.forEach((r) => {
    if (!r.id) return;                       // no id yet -> pass B's job
    const before = prevById[sid(r.id)];
    if (!before) return;
    const prevQty = round3(before.so_quantity);
    const nextQty = round3(r.so_quantity);
    const prevItem = sid(before.item_name);
    const nextItem = sid(r.item_name);
    if (prevItem !== nextItem) {
      changes.push(entry(r, "swap", prevQty, nextQty, prevItem, nextItem, before));
      pushMat(nextItem); pushMat(prevItem);
    } else if (Math.abs(nextQty - prevQty) > 0.0005) {
      changes.push(entry(r, "qty", prevQty, nextQty, prevItem, nextItem, before));
      pushMat(nextItem);
    }
  });
  // Absent from the submitted array = removed. code_node_rPqQy5CD already dropped blank
  // and zero-quantity rows upstream, so a zeroed line reaches us as a removal.
  prevLines.forEach((r) => {
    if (!r.id || nextById[sid(r.id)]) return;
    changes.push(entry(r, "removed", round3(r.so_quantity), 0, sid(r.item_name), "", r));
    pushMat(r.item_name);
  });
}

// An empty `in` / `equalAny` matches every row, so never hand a search a bare [].
return {
  changes: changes,
  changeCount: changes.length,
  materialIds: materialIds.length ? materialIds : ["__none__"],
  emptyList: []
};

// Owns only the rules the downstream documents cannot know: which delivery a line
// belongs to, and how far a quantity may move given what other deliveries already
// took. Pick blocks, invoiced/packed lines, serial shortfalls, over-delivery and
// stock availability are all left to GDheadWorkflow / PPheadWorkflow, which produce
// better messages than a second implementation would.
const mode = {{workflowparams:mode}};
const confirmReversal = {{workflowparams:confirmPickReversal}};
const raiseAnswer = {{workflowparams:raiseGdQty}};
const changes = {{node:code_cd_diff.data.changes}} || [];
const rawGds = {{node:search_cd_gds.data.data}};
const rawPps = {{node:search_cd_pps.data.data}};
const rawItems = {{node:search_cd_items.data.data}};
const rawSetup = {{node:get_cd_setup.data.data}};

const asArray = (v) => (Array.isArray(v) ? v : v ? [v] : []);
const gds = asArray(rawGds);
const pps = asArray(rawPps);
const items = asArray(rawItems);
const setup = asArray(rawSetup)[0] || {};

const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const sid = (v) => String(v === null || v === undefined ? "" : v);
const round3 = (v) => Math.round(num(v) * 1000) / 1000;
const flat = (rows) =>
  (Array.isArray(rows) ? rows : []).flatMap((r) =>
    [r].concat(Array.isArray(r && r.children) ? r.children : [])
  );
const parseArr = (raw) => {
  if (Array.isArray(raw)) return raw;
  if (!raw) return [];
  try { const p = JSON.parse(raw); return Array.isArray(p) ? p : []; } catch (e) { return []; }
};
// The allocation key Picking itself uses (PickingProcessWorkflow code_node_iES7iMKA).
const allocKey = (e) =>
  sid(e.location_id || "no-loc") + "_" + sid(e.batch_id || "no-batch") + "_" +
  sid(e.handling_unit_id || "no-hu");

const itemById = {};
items.forEach((i) => { if (i && i.id) itemById[sid(i.id)] = i; });

// Order UOM -> base UOM. The ITEM is the authority (same lookup GLOBAL_AUTO_ALLOCATION
// and GD_funcProcessGDLineItem use); the row's own base_qty/gd_qty ratio is only a
// derived cache, so it is the last resort -- an already-inconsistent row would
// otherwise propagate its wrong factor into every later edit.
const baseFactorFor = (item, uomId, curQty, curBase) => {
  if (item) {
    if (sid(item.based_uom) === sid(uomId)) { return 1; }   // order UOM IS the base UOM
    const rows = Array.isArray(item.table_uom_conversion) ? item.table_uom_conversion : [];
    const conv = rows.find((c) => sid(c.alt_uom_id) === sid(uomId));
    if (conv && parseFloat(conv.base_qty)) { return parseFloat(conv.base_qty); }
  }
  return curQty > 0 && curBase > 0 ? curBase / curQty : 1;
};

const OFF = {
  blockCode: "", blocked: 0, blockSignal: 0, blockKind: "", blockMessage: "",
  gdDrafts: [], ppDrafts: [], allocRequests: [], affectedSoLineIds: ["__none__"], hasWork: 0
};
if (!changes.length) return OFF;

const block = (msg) => ({
  blockCode: "406", blocked: 1, blockSignal: 1, blockKind: "block", blockMessage: msg,
  gdDrafts: [], ppDrafts: [], allocRequests: [], affectedSoLineIds: ["__none__"], hasWork: 0
});

// ---- index the downstream lines by SO line -------------------------------------
const gdLinesBySoLine = {};
const gdById = {};
gds.forEach((gd) => {
  gdById[sid(gd.id)] = gd;
  flat(gd.table_gd).forEach((ln) => {
    if (!ln || !ln.so_line_item_id) return;
    const k = sid(ln.so_line_item_id);
    (gdLinesBySoLine[k] = gdLinesBySoLine[k] || []).push({ gd: gd, line: ln });
  });
});
const ppLinesBySoLine = {};
const ppById = {};
pps.forEach((pp) => {
  ppById[sid(pp.id)] = pp;
  flat(pp.table_to).forEach((ln) => {
    if (!ln || !ln.so_line_item_id) return;
    const k = sid(ln.so_line_item_id);
    (ppLinesBySoLine[k] = ppLinesBySoLine[k] || []).push({ pp: pp, line: ln });
  });
});

const affected = [];
const allocRequests = [];
const gdEdits = {};   // gdId -> { gd, rows: {gdLineId: patch}, drops: Set-ish map }
const ppEdits = {};
let needRaise = 0;
let needReversal = 0;
const raiseLines = [];
const reversalLines = [];

const editFor = (bag, key, doc) => {
  if (!bag[key]) bag[key] = { doc: doc, rows: {}, drops: {} };
  return bag[key];
};

// Trim an allocation down to `target`, spending unpicked quantity before picked.
// Cutting into picked quantity is exactly the case GD answers with its 413.
const trimAllocation = (entries, pickedEntries, target) => {
  const list = entries.map((e) => Object.assign({}, e));
  const pickedLeft = {};
  pickedEntries.forEach((p) => {
    const k = allocKey(p);
    pickedLeft[k] = round3((pickedLeft[k] || 0) + num(p.gd_quantity));
  });
  let total = list.reduce((s, e) => s + num(e.gd_quantity), 0);
  let remove = round3(total - target);
  let cutIntoPicked = false;
  const take = (freeOnly) => {
    for (let i = list.length - 1; i >= 0 && remove > 0.0005; i--) {
      const qty = num(list[i].gd_quantity);
      if (qty <= 0) continue;
      const k = allocKey(list[i]);
      const picked = Math.min(qty, pickedLeft[k] || 0);
      const avail = freeOnly ? round3(qty - picked) : qty;
      if (avail <= 0) continue;
      const cut = Math.min(avail, remove);
      list[i].gd_quantity = round3(qty - cut);
      remove = round3(remove - cut);
      if (!freeOnly && cut > round3(qty - picked)) cutIntoPicked = true;
      if (picked > 0 && !freeOnly) {
        pickedLeft[k] = round3(Math.max(0, picked - Math.max(0, cut - round3(qty - picked))));
      }
    }
  };
  take(true);
  if (remove > 0.0005) { take(false); }
  return {
    entries: list.filter((e) => num(e.gd_quantity) > 0),
    cutIntoPicked: cutIntoPicked
  };
};

for (const ch of changes) {
  const soLineId = sid(ch.soLineId);
  const label = ch.desc || ch.itemCode || ("SO line " + (ch.lineIndex || soLineId));
  const gdHits = gdLinesBySoLine[soLineId] || [];
  const ppHits = ppLinesBySoLine[soLineId] || [];

  if (mode === "append") {
    // Handled by code_cd_payloads: a new line joins the single Created GD.
    affected.push(soLineId);
    continue;
  }

  const completed = gdHits.filter((h) => sid(h.gd.gd_status) === "Completed");
  const created = gdHits.filter((h) => sid(h.gd.gd_status) === "Created");
  const completedQty = round3(completed.reduce((s, h) => s + num(h.line.gd_qty), 0));

  if (completedQty > 0 && ch.kind === "swap") {
    return block("Item " + label + " has already been delivered on " +
      completed.map((h) => sid(h.gd.delivery_no)).join(", ") +
      ", so the item on that line can no longer be changed.");
  }
  if (ch.kind !== "added" && round3(ch.nextQty) + 0.0005 < completedQty) {
    return block("Item " + label + " has already been delivered " + completedQty + " on " +
      completed.map((h) => sid(h.gd.delivery_no)).join(", ") +
      ". The order quantity cannot be reduced to " + round3(ch.nextQty) + ".");
  }
  const createdGdIds = [];
  created.forEach((h) => {
    const k = sid(h.gd.id);
    if (createdGdIds.indexOf(k) < 0) createdGdIds.push(k);
  });
  if (createdGdIds.length > 1) {
    return block("Item " + label + " is claimed by more than one delivery still at Created (" +
      created.map((h) => sid(h.gd.delivery_no)).join(", ") +
      "). Edit those deliveries one at a time.");
  }

  let touched = 0;

  // ---- Goods Delivery -----------------------------------------------------------
  for (const h of created) {
    touched = 1;
    const line = h.line;
    const gdLineId = sid(line.id);
    const ed = editFor(gdEdits, sid(h.gd.id), h.gd);
    const curQty = round3(line.gd_qty);
    const curOrder = round3(line.gd_order_quantity);
    const pickedQty = round3(line.picked_qty);
    const pickedEntries = parseArr(line.picked_temp_qty_data);
    const entries = parseArr(line.temp_qty_data);

    if (ch.kind === "removed") {
      ed.drops[gdLineId] = 1;
      if (pickedQty > 0) { needReversal = 1; reversalLines.push(label + " (" + pickedQty + " picked)"); }
      continue;
    }
    if (ch.kind === "swap") {
      const item = itemById[sid(ch.nextItem)] || {};
      // A different item means the old base ratio no longer applies.
      const swapFactor = baseFactorFor(item, line.gd_order_uom_id || ch.uomId,
                                       curQty, round3(line.base_qty));
      const swapInit = num(line.gd_initial_delivered_qty);
      ed.rows[gdLineId] = {
        material_id: sid(ch.nextItem),
        material_name: sid(item.material_name || item.material_code || ""),
        gd_material_desc: ch.desc,
        gd_order_quantity: round3(ch.nextQty).toFixed(3),
        gd_qty: round3(curQty).toFixed(3),
        base_qty: round3(curQty * swapFactor).toFixed(3),
        gd_delivered_qty: round3(swapInit + curQty).toFixed(3),
        gd_undelivered_qty: round3(Math.max(0, ch.nextQty - swapInit - curQty)).toFixed(3),
        temp_qty_data: "[]",
        temp_hu_data: "[]",
        view_stock: "",
        _reallocate: 1,
        _baseFactor: swapFactor
      };
      allocRequests.push({
        key: sid(h.gd.id) + "|" + gdLineId,
        gd_id: sid(h.gd.id), gd_line_id: gdLineId,
        material_id: sid(ch.nextItem), quantity: round3(curQty),
        plant_id: sid(h.gd.plant_id), organization_id: sid(h.gd.organization_id),
        existingAllocationData: [], orderUomId: sid(line.gd_order_uom_id || ch.uomId),
        parent_line_id: soLineId, currentDocId: sid(h.gd.id),
        splitPolicy: sid(setup.split_policy || ""), huPriority: sid(setup.hu_priority || ""),
        label: label, gd_no: sid(h.gd.delivery_no)
      });
      if (pickedQty > 0) { needReversal = 1; reversalLines.push(label + " (" + pickedQty + " picked)"); }
      continue;
    }

    // ch.kind === "qty" -- anchored on gd_order_quantity so a retry is a no-op.
    const delta = round3(ch.nextQty - curOrder);
    const ceiling = round3(Math.max(0, ch.nextQty - num(ch.deliveredQty)));
    const patch = { gd_order_quantity: round3(ch.nextQty).toFixed(3) };
    const curBase = round3(line.base_qty);
    const baseFactor = baseFactorFor(itemById[sid(line.material_id)],
                                     line.gd_order_uom_id || ch.uomId, curQty, curBase);
    let finalQty = curQty;

    if (delta > 0.0005) {
      if (raiseAnswer !== "Yes" && raiseAnswer !== "No") {
        needRaise = 1;
        raiseLines.push(label + ": " + curQty + " -> " + round3(Math.min(curQty + delta, ceiling)));
        continue;
      }
      if (raiseAnswer === "Yes") {
        const target = round3(Math.min(curQty + delta, ceiling));
        const addQty = round3(target - curQty);
        if (addQty > 0.0005) {
          finalQty = target;
          patch.gd_qty = target.toFixed(3);
          patch._reallocate = 1;
          patch._baseFactor = baseFactor;
          allocRequests.push({
            key: sid(h.gd.id) + "|" + gdLineId,
            gd_id: sid(h.gd.id), gd_line_id: gdLineId,
            material_id: sid(line.material_id), quantity: addQty,
            plant_id: sid(h.gd.plant_id), organization_id: sid(h.gd.organization_id),
            // The row's own entries are handed back as existing so the allocator never
            // re-serves stock this delivery already holds, and the picked entries stay put.
            existingAllocationData: entries.map((e) => ({
              location_id: e.location_id, batch_id: e.batch_id,
              handling_unit_id: e.handling_unit_id, quantity: num(e.gd_quantity)
            })),
            orderUomId: sid(line.gd_order_uom_id || ch.uomId),
            parent_line_id: soLineId, currentDocId: sid(h.gd.id),
            splitPolicy: sid(setup.split_policy || ""), huPriority: sid(setup.hu_priority || ""),
            label: label, gd_no: sid(h.gd.delivery_no)
          });
        }
      }
    } else if (delta < -0.0005) {
      const target = round3(Math.min(curQty, ceiling));
      if (target < curQty - 0.0005) {
        const trimmed = trimAllocation(entries, pickedEntries, target);
        finalQty = target;
        patch.gd_qty = target.toFixed(3);
        patch.base_qty = round3(target * baseFactor).toFixed(3);
        patch.temp_qty_data = JSON.stringify(trimmed.entries);
        if (trimmed.cutIntoPicked || target < pickedQty - 0.0005) {
          needReversal = 1;
          reversalLines.push(label + ": " + pickedQty + " picked, delivery now " + target);
        }
      }
    }
    // code_node_GKc0ALEe recomputes packing_qty and net_weight from gd_qty but only
    // FORMATS base_qty and gd_delivered_qty, so a stale pair would survive the save --
    // and ReorderRedisWorkflow reads base_qty/gd_qty as the line's UOM factor.
    const initDel = num(line.gd_initial_delivered_qty);
    patch.gd_delivered_qty = round3(initDel + finalQty).toFixed(3);
    patch.gd_undelivered_qty = round3(Math.max(0, ch.nextQty - initDel - finalQty)).toFixed(3);
    ed.rows[gdLineId] = Object.assign(ed.rows[gdLineId] || {}, patch);
  }

  // ---- Picking Plan -------------------------------------------------------------
  const ppLive = ppHits.filter((h) => {
    const st = sid(h.pp.to_status);
    return st !== "Cancelled" && st !== "Completed" && st !== "Draft";
  });
  for (const h of ppLive) {
    touched = 1;
    const line = h.line;
    const ppLineId = sid(line.id);
    const ed = editFor(ppEdits, sid(h.pp.id), h.pp);
    const curQty = round3(line.to_qty);
    const curOrder = round3(line.to_order_quantity);
    const pickedQty = round3(line.picked_qty);
    const entries = parseArr(line.temp_qty_data);
    const pickedEntries = parseArr(line.picked_temp_qty_data);

    if (ch.kind === "removed") { ed.drops[ppLineId] = 1; continue; }
    if (ch.kind === "swap") {
      // PP's own gate refuses an item swap on a picked line; hand it over rather than
      // duplicating that rule, but do not attempt to re-allocate the plan ourselves.
      ed.rows[ppLineId] = {
        material_id: sid(ch.nextItem),
        to_order_quantity: round3(ch.nextQty).toFixed(3),
        temp_qty_data: "[]"
      };
      continue;
    }
    const patch = { to_order_quantity: round3(ch.nextQty).toFixed(3) };
    const ceiling = round3(Math.max(0, ch.nextQty - num(ch.deliveredQty)));
    if (round3(ch.nextQty) < curOrder - 0.0005) {
      const target = round3(Math.min(curQty, ceiling));
      if (target < curQty - 0.0005) {
        patch.to_qty = target.toFixed(3);
        patch.temp_qty_data = JSON.stringify(trimAllocation(entries, pickedEntries, target).entries);
      }
    }
    ed.rows[ppLineId] = Object.assign(ed.rows[ppLineId] || {}, patch);
  }

  if (touched) affected.push(soLineId);
}

// A confirm must be answered before anything is written, so it outranks the work.
if (needRaise) {
  return {
    blockCode: "414", blocked: 1, blockSignal: 3, blockKind: "confirmRaise",
    blockMessage: "The order quantity went up on:<br><br>" + raiseLines.join("<br>") +
      "<br><br>Add the extra quantity to the delivery that is already Created, or leave it outstanding for a later delivery?",
    gdDrafts: [], ppDrafts: [], allocRequests: [], affectedSoLineIds: ["__none__"], hasWork: 0
  };
}
if (needReversal && confirmReversal !== "Yes") {
  return {
    blockCode: "413", blocked: 1, blockSignal: 2, blockKind: "confirmReversal",
    blockMessage: "This change reverses quantities already picked:<br><br>" +
      reversalLines.join("<br>") +
      "<br><br>The Picking and the stock reservations will be updated. Proceed?",
    gdDrafts: [], ppDrafts: [], allocRequests: [], affectedSoLineIds: ["__none__"], hasWork: 0
  };
}

// ---- materialise the drafts ------------------------------------------------------
const applyRows = (doc, tableKey, ed, isBundleParent) => {
  const copy = JSON.parse(JSON.stringify(doc));
  const walk = (rows) =>
    (Array.isArray(rows) ? rows : []).map((row) => {
      const id = sid(row.id);
      if (ed.drops[id]) return null;
      const patched = Object.assign({}, row, ed.rows[id] || {});
      if (Array.isArray(row.children)) {
        patched.children = walk(row.children).filter((c) => c);
      }
      // A bundle parent whose children are all gone has nothing left to deliver.
      if (isBundleParent(patched) && Array.isArray(patched.children) && !patched.children.length) {
        return null;
      }
      return patched;
    }).filter((r) => r);
  copy[tableKey] = walk(copy[tableKey]);
  return copy;
};

const gdDrafts = [];
Object.keys(gdEdits).forEach((gdId) => {
  const ed = gdEdits[gdId];
  const draft = applyRows(ed.doc, "table_gd", ed,
    (r) => r.item_bundle_id && !r.material_id);
  const stockRows = flat(draft.table_gd).filter((r) => r && r.material_id);
  if (!stockRows.length) {
    gdDrafts.push({ empty: 1, gd_no: sid(ed.doc.delivery_no) });
    return;
  }
  draft.gd_status = "Created";
  gdDrafts.push({
    gd_id: gdId, gd_no: sid(ed.doc.delivery_no), empty: 0,
    // Ordered so the delivery most likely to refuse runs while nothing is written yet.
    pickWeight: flat(draft.table_gd).reduce((s, r) => s + num(r && r.picked_qty), 0),
    allData: draft
  });
});
const emptied = gdDrafts.filter((g) => g.empty === 1);
if (emptied.length) {
  return block("Removing that line would leave delivery " +
    emptied.map((g) => g.gd_no).join(", ") +
    " with nothing to deliver. Cancel that delivery first.");
}
gdDrafts.sort((a, b) => b.pickWeight - a.pickWeight);

const ppDrafts = [];
Object.keys(ppEdits).forEach((ppId) => {
  const ed = ppEdits[ppId];
  const draft = applyRows(ed.doc, "table_to", ed, (r) => r.item_bundle_id && !r.material_id);
  const stockRows = flat(draft.table_to).filter((r) => r && r.material_id);
  if (!stockRows.length) return;
  draft.to_status = "Created";
  ppDrafts.push({ pp_id: ppId, pp_no: sid(ed.doc.to_id || ed.doc.to_no), allData: draft });
});

return {
  blockCode: "", blocked: 0, blockSignal: 0, blockKind: "", blockMessage: "",
  gdDrafts: gdDrafts, ppDrafts: ppDrafts, allocRequests: allocRequests,
  affectedSoLineIds: affected.length ? affected : ["__none__"],
  hasWork: gdDrafts.length || ppDrafts.length ? 1 : 0
};

// Append mode allocates each new line from scratch; adjust mode's requests were already
// built by code_cd_plan.
const mode = {{workflowparams:mode}};
const planned = {{node:code_cd_plan.data.allocRequests}} || [];
const rawSetup0 = {{node:get_cd_setup.data.data}};
const setup0 = (Array.isArray(rawSetup0) ? rawSetup0 : rawSetup0 ? [rawSetup0] : [])[0] || {};
// Same defaults GDheadWorkflow's code_node_Htpcyp8t applies.
const enrich = (r) => Object.assign({}, r, {
  allocationStrategy: String(setup0.default_strategy_id || "RANDOM"),
  huPriority: String(setup0.hu_priority || "Loose First"),
  splitPolicy: String(setup0.split_policy || "ALLOW_SPLIT"),
  allowMixedItem: setup0.allow_mixed_item === 0 ? 0 : 1,
  lineMaterials: [String(r.material_id || "")],
  huData: []
});
if (mode !== "append") { return { requests: planned.map(enrich) }; }

const changes = {{node:code_cd_diff.data.changes}} || [];
const rawGds = {{node:search_cd_gds.data.data}};
const rawSetup = {{node:get_cd_setup.data.data}};
const asArray = (v) => (Array.isArray(v) ? v : v ? [v] : []);
const sid = (v) => String(v === null || v === undefined ? "" : v);
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const round3 = (v) => Math.round(num(v) * 1000) / 1000;
const setup = asArray(rawSetup)[0] || {};

const gds = asArray(rawGds).filter((g) => sid(g.gd_status) === "Created");
if (gds.length !== 1) { return { requests: [] }; }
const gd = gds[0];

const requests = changes
  .filter((c) => c.kind === "added")
  .map((c) => ({
    key: "append|" + sid(c.soLineId),
    gd_id: sid(gd.id), gd_line_id: "",
    material_id: sid(c.nextItem),
    quantity: round3(Math.max(0, num(c.nextQty) - num(c.deliveredQty) - num(c.plannedQty))),
    plant_id: sid(gd.plant_id), organization_id: sid(gd.organization_id),
    existingAllocationData: [], orderUomId: sid(c.uomId),
    parent_line_id: sid(c.soLineId), currentDocId: sid(gd.id),
    splitPolicy: sid(setup.split_policy || ""), huPriority: sid(setup.hu_priority || ""),
    label: c.desc || c.itemCode || sid(c.soLineId), gd_no: sid(gd.delivery_no)
  }))
  .filter((r) => r.quantity > 0.0005);

return { requests: requests.map(enrich) };

// Per-run redis namespace, so concurrent saves never share an accumulator.
const soId = {{workflowparams:so_id}} || "";
const mode = {{workflowparams:mode}} || "";

return {
  unique: String(soId) + "_" + String(mode) + "_" + Date.now(),
};

// One entry per allocation attempt. GLOBAL_ALLOCATION returns 400 with a message when
// there is not enough unrestricted stock; nothing is written by it either way.
const raw = {{node:get_cd_alloc.data}};
let results = [];
if (raw) { results = typeof raw === "string" ? JSON.parse(raw) : raw; }
if (!Array.isArray(results)) results = [];

results.push({
  key: {{node:loop_cd_alloc.key}} || "",
  gd_id: {{node:loop_cd_alloc.gd_id}} || "",
  gd_line_id: {{node:loop_cd_alloc.gd_line_id}} || "",
  gd_no: {{node:loop_cd_alloc.gd_no}} || "",
  label: {{node:loop_cd_alloc.label}} || "",
  code: String({{node:wf_cd_alloc.data.code}} || ""),
  message: {{node:wf_cd_alloc.data.message}} || "",
  allocationData: {{node:wf_cd_alloc.data.allocationData}} || []
});

return { results: results };

// Splice the allocation results into the drafts. In append mode the new SO lines are
// turned into GD rows here, because only now do they carry a persisted row id.
const mode = {{workflowparams:mode}};
const drafts = {{node:code_cd_plan.data.gdDrafts}} || [];
const ppDrafts = {{node:code_cd_plan.data.ppDrafts}} || [];
const changes = {{node:code_cd_diff.data.changes}} || [];
const rawAlloc = {{node:get_cd_alloc_final.data}};
const rawGds = {{node:search_cd_gds.data.data}};
const rawItems = {{node:search_cd_items.data.data}};

const asArray = (v) => (Array.isArray(v) ? v : v ? [v] : []);
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const sid = (v) => String(v === null || v === undefined ? "" : v);
const round3 = (v) => Math.round(num(v) * 1000) / 1000;
const flat = (rows) =>
  (Array.isArray(rows) ? rows : []).flatMap((r) =>
    [r].concat(Array.isArray(r && r.children) ? r.children : [])
  );
const parseArr = (raw) => {
  if (Array.isArray(raw)) return raw;
  if (!raw) return [];
  try { const p = JSON.parse(raw); return Array.isArray(p) ? p : []; } catch (e) { return []; }
};

let allocResults = [];
if (rawAlloc) { allocResults = typeof rawAlloc === "string" ? JSON.parse(rawAlloc) : rawAlloc; }
if (!Array.isArray(allocResults)) allocResults = [];

const failed = allocResults.filter((r) => r && String(r.code) !== "200" && String(r.code) !== "206");
if (failed.length) {
  const lead = mode === "append"
    ? "The sales order was saved, but the new line could not be added to the delivery:<br><br>"
    : "";
  return {
    gdPayloads: [], ppPayloads: [], allocFailed: 1,
    allocMessage: lead + failed
      .map((f) => (f.label || "item") + " on " + (f.gd_no || "the delivery") + ": " +
        (f.message || "could not be allocated"))
      .join("<br>")
  };
}
const allocByKey = {};
allocResults.forEach((r) => { if (r && r.key) allocByKey[sid(r.key)] = r; });

// GLOBAL_ALLOCATION returns balances; temp_qty_data wants the GD-shaped record
// (same fields code_node_hifFKzmo writes in GDheadWorkflow).
const toTempEntry = (alloc, materialId, plantId, orgId) => {
  const rec = {
    material_id: sid(materialId),
    location_id: alloc.location_id,
    batch_id: alloc.batch_id || null,
    unrestricted_qty: alloc.original_unrestricted_qty || alloc.unrestricted_qty,
    plant_id: sid(plantId),
    organization_id: sid(orgId),
    is_deleted: 0,
    gd_quantity: num(alloc.gd_quantity),
    balance_id: alloc.balance_id || ""
  };
  if (alloc.source === "hu" && alloc.handling_unit_id) {
    rec.handling_unit_id = alloc.handling_unit_id;
  }
  return rec;
};

const gdPayloads = [];
drafts.forEach((d) => {
  const allData = d.allData;
  flat(allData.table_gd).forEach((row) => {
    if (!row || !row._reallocate) return;
    const res = allocByKey[sid(d.gd_id) + "|" + sid(row.id)];
    const baseFactor = num(row._baseFactor) || 1;
    delete row._reallocate;
    delete row._baseFactor;
    if (!res) return;
    const fresh = asArray(res.allocationData).map((a) =>
      toTempEntry(a, row.material_id, allData.plant_id, allData.organization_id));
    // A raise appends, so every entry the picker already worked stays byte-identical.
    const kept = parseArr(row.temp_qty_data);
    const merged = kept.concat(fresh);
    row.temp_qty_data = JSON.stringify(merged);
    // The allocator can return less than asked, so every qty-derived field is restated
    // from the merged total rather than from the target the plan node assumed.
    const finalQty = round3(merged.reduce((s, e) => s + num(e.gd_quantity), 0));
    const initDel = num(row.gd_initial_delivered_qty);
    row.gd_qty = finalQty.toFixed(3);
    row.base_qty = round3(finalQty * baseFactor).toFixed(3);
    row.gd_delivered_qty = round3(initDel + finalQty).toFixed(3);
    row.gd_undelivered_qty =
      round3(Math.max(0, num(row.gd_order_quantity) - initDel - finalQty)).toFixed(3);
    const huRows = merged.filter((e) => e.handling_unit_id);
    if (huRows.length) {
      row.temp_hu_data = JSON.stringify(huRows.map((e) => ({
        row_type: "item", handling_unit_id: e.handling_unit_id,
        material_id: e.material_id, location_id: e.location_id,
        batch_id: e.batch_id || null, balance_id: e.balance_id || "",
        deliver_quantity: num(e.gd_quantity), item_quantity: num(e.unrestricted_qty)
      })));
    }
  });
  gdPayloads.push({ gd_id: d.gd_id, gd_no: d.gd_no, allData: allData });
});

// ---- append mode: new SO lines join the single Created GD -------------------------
if (mode === "append") {
  const gds = asArray(rawGds).filter((g) => sid(g.gd_status) === "Created");
  const items = asArray(rawItems);
  const itemById = {};
  items.forEach((i) => { if (i && i.id) itemById[sid(i.id)] = i; });
  const uomFactor = (item, uomId) => {
    if (!item) { return 1; }
    if (sid(item.based_uom) === sid(uomId)) { return 1; }
    const rows = Array.isArray(item.table_uom_conversion) ? item.table_uom_conversion : [];
    const conv = rows.find((c) => sid(c.alt_uom_id) === sid(uomId));
    return conv && parseFloat(conv.base_qty) ? parseFloat(conv.base_qty) : 1;
  };
  const added = changes.filter((c) => c.kind === "added");
  if (!gds.length || !added.length) {
    return { gdPayloads: gdPayloads, ppPayloads: ppDrafts, allocFailed: 0, allocMessage: "" };
  }
  if (gds.length > 1) {
    return {
      gdPayloads: [], ppPayloads: [], allocFailed: 1,
      allocMessage: "The sales order was saved, but it has more than one delivery still at Created (" +
        gds.map((g) => sid(g.delivery_no)).join(", ") +
        "), so the new line was not added to any of them. Add it to the right delivery manually."
    };
  }
  const gd = JSON.parse(JSON.stringify(gds[0]));
  added.forEach((ch) => {
    const res = allocByKey["append|" + sid(ch.soLineId)];
    const item = itemById[sid(ch.nextItem)] || {};
    const entries = res
      ? asArray(res.allocationData).map((a) =>
          toTempEntry(a, ch.nextItem, gd.plant_id, gd.organization_id))
      : [];
    const qty = round3(entries.reduce((s, e) => s + num(e.gd_quantity), 0));
    gd.table_gd = (Array.isArray(gd.table_gd) ? gd.table_gd : []).concat([{
      material_id: sid(ch.nextItem),
      material_name: sid(item.material_name || item.material_code || ""),
      gd_material_desc: ch.desc,
      so_line_item_id: sid(ch.soLineId),
      line_so_id: sid(gd.so_id && gd.so_id[0] ? gd.so_id[0] : gd.so_id),
      line_so_no: sid(gd.so_no),
      gd_order_quantity: round3(ch.nextQty).toFixed(3),
      gd_order_uom_id: sid(ch.uomId),
      gd_initial_delivered_qty: round3(ch.deliveredQty).toFixed(3),
      gd_qty: qty.toFixed(3),
      base_qty: round3(qty * uomFactor(item, ch.uomId)).toFixed(3),
      gd_delivered_qty: round3(num(ch.deliveredQty) + qty).toFixed(3),
      gd_undelivered_qty: round3(Math.max(0, num(ch.nextQty) - num(ch.deliveredQty) - qty)).toFixed(3),
      temp_qty_data: JSON.stringify(entries),
      view_stock: "",
      packing_conversion: 0,
      weight_conversion: 0,
      picking_status: "Created"
    }]);
  });
  gd.gd_status = "Created";
  return {
    gdPayloads: [{ gd_id: sid(gd.id), gd_no: sid(gd.delivery_no), allData: gd }],
    ppPayloads: [], allocFailed: 0, allocMessage: ""
  };
}

return { gdPayloads: gdPayloads, ppPayloads: ppDrafts, allocFailed: 0, allocMessage: "" };

const raw = {{node:get_cd_res_gd.data}};
let results = [];
if (raw) { results = typeof raw === "string" ? JSON.parse(raw) : raw; }
if (!Array.isArray(results)) results = [];

// Never test for "400": PPheadWorkflow's item-not-found return carries no response_value
// at all, so a failure can arrive as an empty code.
const code = String({{node:wf_cd_gd.data.code}} || "");
results.push({
  doc: "GD",
  doc_no: {{node:loop_cd_gd.gd_no}} || "",
  code: code,
  ok: code === "200" ? 1 : 0,
  message: {{node:wf_cd_gd.data.message}} || "",
  note: {{node:wf_cd_gd.data.pickingReversalNote}} || ""
});

return { results: results };

const raw = {{node:get_cd_res_pp.data}};
let results = [];
if (raw) { results = typeof raw === "string" ? JSON.parse(raw) : raw; }
if (!Array.isArray(results)) results = [];

const code = String({{node:wf_cd_pp.data.code}} || "");
results.push({
  doc: "Picking Plan",
  doc_no: {{node:loop_cd_pp.pp_no}} || "",
  code: code,
  ok: code === "200" ? 1 : 0,
  message: {{node:wf_cd_pp.data.message}} || "",
  note: ""
});

return { results: results };

const mode = {{workflowparams:mode}};
const raw = {{node:get_cd_res_final.data}};
let results = [];
if (raw) { results = typeof raw === "string" ? JSON.parse(raw) : raw; }
if (!Array.isArray(results)) results = [];

const rawLines = {{node:search_cd_solines.data.data}};
const lines = Array.isArray(rawLines) ? rawLines : rawLines ? [rawLines] : [];
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };

// planned_qty as the downstream documents just left it. SOsaveWorkflow's whole-array
// table_so write would otherwise put the browser's copy back over the top.
const soLineCounters = lines.map((l) => ({
  id: String(l.id),
  planned_qty: num(l.planned_qty),
  delivered_qty: num(l.delivered_qty)
}));

const ok = results.filter((r) => r.ok === 1);
const bad = results.filter((r) => r.ok !== 1);
const note = ok.map((r) => r.note).filter((n) => n).join("<br><br>");

if (!bad.length) {
  return {
    code: "200",
    message: "",
    blockKind: "",
    blockSignal: 0,
    pickingReversalNote: note,
    soLineCounters: soLineCounters,
    appliedSummary: results
  };
}

// Pass B runs after the sales order row is written, so it must never claim otherwise.
// In pass A nothing upstream is saved yet, and payloads are anchored on
// gd_order_quantity, so a document already updated is a no-op on the next attempt.
const lead = mode === "append"
  ? "The sales order was saved, but the new line could not be added to the delivery:<br><br>"
  : ok.length
    ? "The sales order was not saved. " + ok.length +
      " linked document(s) were already updated (" + ok.map((r) => r.doc_no).join(", ") +
      ") and saving again will leave them as they are.<br><br>"
    : "The sales order was not saved.<br><br>";

const tail = mode === "append"
  ? "<br><br>Add that line to the delivery manually."
  : bad.some((r) => r.code === "" || r.code === "400") && ok.length
    ? "<br><br>If the same error repeats, that document must be corrected directly."
    : "";

return {
  code: "406",
  message: lead + bad.map((r) => (r.doc_no || r.doc) + ": " + (r.message || "failed")).join("<br>") + tail,
  blockKind: "block",
  blockSignal: 1,
  pickingReversalNote: note,
  soLineCounters: soLineCounters,
  appliedSummary: results
};
